def comps(g,val):
    R,C=len(g),len(g[0]); seen=set(); res=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==val and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for d in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+d[0],b+d[1]
                        if 0<=x<R and 0<=y<C and g[x][y]==val and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                res.append(sorted(comp))
    return res
